},
[87318] = { en="Hearts of the Lost", ai=true,
[===[Серця загублених]===],
[===[На віадуку Тандола небезпечно відтоді, як дворфи Темного Заліза підірвали міст, але я не чекала, що наткнуся там на них самих!

