[94232] = { en="Craftsman's Writ: Minor Recombobulator", ai=true,
[===[Замовлення майстра: Малий рекомбобулятор]===],
[===[<У записці, написаній вицвілим чорнилом, замовляють 1 малий рекомбобулятор, а також вказано місце доставки й оплату. Унизу зазначено, що це замовлення можна передати іншому.>]===],
[===[Здобудьте предмети, замовлені клієнтом, і доставте їх до місця, позначеного на вашій мапі. Щоб завершити угоду, це замовлення має бути при вас.]===],
[===[У нас із тобою є якісь справи?]===],
[===[Не знаю, чого я чекав, коли замовляв пристрій для зняття прокльонів, але цей малий рекон... рокомб... тьху, малий як-там-його — це точно не воно!

Слухай, я знаю, яка морока з поверненням коштів, а на це в мене НЕМАЄ часу. Нам обом буде значно простіше, якщо я просто заберу в тебе цю штуку, а наступне замовлення складу точніше.

Заради нас обох сподіваймося, що хоч наступного разу ти не схибиш!]===],
},
[94242] = { en="Craftsman's Writ: Pilferer's Gloves", ai=true,
[===[Замовлення майстра: Рукавиці злодія]===],
