[96800] = { en="Past Due", ai=true,
[===[Прострочено]===],
[===[Гей, ти, {клас:к}. Маю справу, в якій мені знадобилася б допомога.

Так уже склалося, що я пишу дисертацію про древніх майстрів рун Диких Молотів з Ґрім-Батола, і для завершення дослідження мені потрібен один конкретний том. За нашими обліковими книгами, маг на ім'я Доан узяв цю книгу в старій бібліотеці Даларана ще до Третьої війни і так її й не повернув!

Тепер арканіст Доан засів у Багряному монастирі в Тірісфальському переліссі. Поверни мені цю книгу — і на тебе чекає щедра винагорода.]===],
[===[Заберіть книгу "Втрачена магія майстрів рун" з Багряного монастиря.]===],
nil,
nil,
},
[97005] = { en="Chol'aruk the Ravener", ai=true,
[===[Чол'арук Ненажера]===],
[===[Ходять чутки про велетенську потвору, що влаштувала лігво в печері на північний захід звідси, на плато, відомому як Колючий згірок. Бритвогриві називають її Чол'арук, або «Ненажера», і ті, хто її бачив, кажуть, що вона така здоровенна, що може проковтнути орка цілком.

Мало хто вірить таким байкам, але я вірю... бо й сам бився з подібною. Заради честі тих, кого я втратив через цих тварюк, цей звір мусить померти.

Збери сильних союзників і знайди лігво Чол'арука. Вбий потвору й принеси мені її голову.]===],
[===[Принесіть голову Чол'арука Бейнгему в Степи.]===],
[===[Щоб здолати одну таку істоту, нас знадобилося шестеро, і вона все одно встигла вбити всіх, крім мене та ще одного, перш ніж ми її повалили.

Так далеко від земель Альянсу мені варто було б дати їй спокій. Світло свідок, я не втрачу сну через кількох тауренських дикунів чи орківських громил. Проте честь моїх полеглих побратимів вимагає дій.]===],
[===[Мої загиблі бійці спочиватимуть спокійніше, знаючи, що у світі на одне таке чудовисько менше. Ти добре {стать:впорався:впоралася}, ти {стать:справжній і непохитний захисник:справжня і непохитна захисниця} Альянсу. Дякую.

Іди з честю, {ім'я:к}.]===],
},
[97220] = { en="Philmor's Favor", ai=true,
[===[Послуга Філморові]===],
[===[Цього тижня нам щодня бракує вантажників.

Не хочеш трохи розвантажити наш графік перевезень?

Віднеси цей пакунок до входу в комору Брами. Він у сирній крамниці Тріас, на другому поверсі. Господиня, Елейн, добре знає про ці доставки. Вантажі до Брами часто прибувають без зайвого розголосу, щоб офіцери варти могли влаштовувати урочисті сюрпризи.]===],
[===[Віднесіть вантаж із брами до входу в комору в сирній крамниці Тріас, що в Торговому районі.]===],
[===[Хочеш наповнити ящик нашими найкращими витриманими головками сиру?]===],
[===[Ой, леле. Ти гадаєш, ми самі тягтимемо це сходами нагору? Поки ти не доставиш вантаж, за цілість цінностей відповідаєш ти.]===],
},
[97222] = { en="Gatehouse Goods", ai=true,
[===[Вантаж для Брами]===],
[===[Так, це лише один проліт сходів, але якщо прохання таке дрібне, то тобі неважко буде самотужки завершити доставку!

Сирна крамниця Тріас не належить до Брами й не має стосунку до їхніх запасів, але наші будівлі мають спільний поверх.

Постав скриню під дверима їхньої комори — варта регулярно присилає когось забрати вантаж. Вони побачать, що пакунок прибув, і занесуть його всередину, коли повертатимуться на пост.]===],
[===[Віднесіть вантаж із брами сходами нагору в крамниці Тріас і залиште його під дверима.]===],
nil,
[===[Ага. Ці двері невипадково відчиняються всередину, до них, — щоб їм не загороджували прохід ті, хто кидає речі де заманеться.

Вважай нас діловими знайомими, {клас:к}.

Ми поважаємо твою справу й чекаємо, що ти поважатимеш нашу.]===],
tasks = { ["Gatehouse Shipment delivered"] = [===[Вантаж із брами доставлено]===] },
},
[97234] = { en="Reading Room", ai=true,
[===[Читальна зала]===],
[===[Ти тут, щоб обговорити глибинний зміст наших славетних легенд? Ні?

Що ж, коли закінчиш тут роздивлятися, можеш віднести це до бібліотеки замість мене? Ми обмінюємо деякі з наших менш популярних творів на сучаснішу літературу. У мене є список томів, які, я певен, бібліотекар зможе дістати для нас у межах нашої чинної домовленості.

Якщо допоможеш, клубне частування — за наш рахунок.]===],
[===[Віднесіть запаковану літературу до бібліотеки Штормовію.]===],
[===[Будь ласка, говори тихіше.]===],
[===[Ану подивимося. Книжковий клуб Роя, так? Я впізнаю цей спосіб пакування.

Що ж, якщо він каже, що саме про це люди хочуть говорити, то я не проти. Матеріали, які ми отримуємо назад, завжди в такому ж доброму стані, як і тоді, коли ми їх позичали, тож ми знаємо, що до них ставляться з повагою, хоч би якими провокативними були слова.]===],
},
[97236] = { en="Fang of Githyiss", ai=true,
[===[Ікло Ґітісс]===],
[===[Свіжий зразок від звіра такого розміру — неабияка знахідка. Можливо, когось в Альдрассілі, хто знається на вивченні павуків, зацікавить це ікло.]===],
[===[Доставте ікло Ґітісс тому, хто в Альдрассілі цікавиться вивченням павуків.]===],
nil,
[===[Так-так. Як же я люблю сюрпризи, {ім'я:к}.

Цей зразок неодмінно допоможе моїм дослідженням.]===],
},
[97237] = { en="Shelf Picked", ai=true,
[===[Добірка з полиць]===],
[===[Я перевірив наш каталог, і всі видання, які зазначив пан Льюелз, наразі є в наявності.

Проте знімати їх з полиць тобі доведеться самостійно. Пильність — частина обов'язків бібліотекаря, тож я повертаюся до нагляду та ведення обліку.

Те, що ти віднесеш ці книги Рою від його імені, не покладе на тебе відповідальності за їх повернення: як і з його запискою, ти лише офіційний кур'єр книжкового клубу. Цей тягар нестиме їхній заклад.

Всього доброго, {ім'я:к}.]===],
[===[Знайдіть кожне з видань, що лежать десь у бібліотеці, а тоді поверніться до Роя Льюелза в Парк у Штормовії.]===],
[===[Тільки-но за тобою зачинилися двері, як усе, що треба було зробити, вилетіло з голови, еге ж? З усіма буває.]===],
[===[Ось вони! Деякі навіть пахнуть чимось екзотичним! Чудово, не можу дочекатися, коли ми влаштуємо жваві дискусії про ці твори.

У підвалі, після закриття, звісно.

Дякую, що так швидко {стать:обернувся:обернулася}, {ім'я:к}. Як і обіцяв, усе за рахунок закладу. Ми тут тримаємо слово.]===],
},
[97263] = { en="Your Package Has Arrived", ai=true,
[===[Ваш пакунок прибув]===],
[===[<Біля поштової скриньки залишено кілька загублених пакунків. Ви помічаєте, що на одному з них указано доставку з Орлиного піку до Залізогарту, для Ельдруна Бурелама. На ньому позначка "терміново".>]===],
[===[Доставте Ельдрунові його загублений пакунок.]===],
[===[Що це в тебе там?]===],
[===[Що?! Я щодня ходжу до поштової скриньки біля банку, шукаючи цей пакунок! Цьому місту треба нарешті розібратися зі своїм плануванням. Тут не так легко орієнтуватися, як в Орлиному піку!

Подивімося, що тут у мене... інструменти для різьблення тотемів... запасна сокира... якийсь гоблінський пристрій? Я такого не замовляв! А, просто відішлю назад.

Е-е, гм... Тобто... дякую, що {стать:приніс:принесла} мені все це. Ось дещо за твої клопоти.]===],
},
[97277] = { en="Grund and Gozwin", ai=true,
[===[Ґрунд і Ґозвін]===],
[===[Ой, я саме стояв спиною, готував печеню з кнура, аж чую — мій приятель Ґозвін верещить не своїм голосом!

Обернувся — а там тільки лихі ікла та щось розмите промайнуло. Такі здоровенні лапи! Сніжний леопард тягнув свою гномську здобич геть. Я схопив рушницю й вистрілив понад звіром. Той кинув його й дременув.

На щастя, він устиг тільки глибоко подряпати старого Ґоза.

Повертайся до табору на північно-західних пагорбах і забери робочий журнал Ґозвіна. І вбий того сніжного леопарда, якщо побачиш!]===],
[===[Знайдіть табір Ґрунда й Ґозвіна на пагорбах на північному заході. Поверніть робочий журнал Ґозвіна та вбийте сніжного леопарда-скрадача.]===],
[===[Бідолашний Ґоз більше переймається своїм механоходом, ніж собою. Каже, як хтось накладе лапу на той робочий журнал, то йому гаплик. Ха! Я ж йому казав: лишай роботу вдома!]===],
[===[Еге ж, не дивно, що той сніжний леопард ласував кнуром, якого ми готували на печеню!

Тепер, коли ти {стать:приніс:принесла} його журнал, у Ґоза буде на одну турботу менше. Може, тепер він зосередить усі сили на тому, щоб звестися на ноги.

Дякую, {ім'я:к}. Візьми дещицю на знак моєї вдячності — за довгу дорогу і за захист пагорбів.]===],
},
[97420] = { en="Reduce, Reuse, Reconcile", ai=true,
[===[Зменшуй, використовуй повторно, примиряйся]===],
[===[Мені треба когось попросити про послугу, а ти, схоже, з тих, хто радо допомагає!

Бачиш оцю красуню? Хіба не диво? Це моя найновіша перегонова машина, я сам її спроєктував і зібрав, бо ДЕХТО не захотів допомогти. Хочу виставити її на перегони в Тисячі Шипів, але їй бракує трохи прудкості.

Я, звісно, надто вродливий, щоб бути гобліном, і знаю, що їхній техніці довіряти не варто, але чув, що ТзНБ "Авантюра" натрапило на рідке золото біля озера. Певен, вони не будуть проти, якщо ти, е-е, позичиш трохи? Вони навіть не помітять!]===],
[===[Добудьте 5 діжок сирої нафти на об'єктах ТзНБ "Авантюра" біля озера Назферіті, а потім поверніться до Кназа Грубопала в Тернисту долину.]===],
nil,
nil,
},
[97894] = { en="Business in Auberdine", ai=true,
[===[Справи в Аубердіні]===],
[===[Радий знайомству! Мене звати Борґус, з єдиної і неповторної родини Сталеруків. На Сталерука завжди можна покластися, коли треба чесна угода!

Кілька тижнів тому мій брат Ґорбольд пристав до торгової ятки в Аубердіні. Там можна заробити купу монет, постачаючи кораблі, скажу я тобі! От щасливчик, хай йому грець.

Відтоді я від нього нічого не чув. Не проти його провідати, якщо тобі в той бік?

У гавані стоїть новий корабель, який доправить тебе просто туди. Іди до найпівденнішого причалу, не проминеш!]===],
[===[Провідайте Ґорбольда Сталерука в Аубердіні, що в Темнобережжі.

Борґус згадував про корабель біля найпівденнішого причалу в гавані Штормовію, який може вас туди доправити.]===],
nil,
[===[Старий Борґі тебе прислав? Завжди про мене дбає.

Нам тут точно не завадить ще одна пара рук. Після нещодавньої трагедії торгівля майже зупинилася, і, гадаю, ти можеш допомогти все виправити.]===],
tasks = { ["Take the boat to Auberdine and find Gorbold Steelhand."] = [===[Сісти на корабель до Аубердіна й знайти Ґорбольда Сталерука.]===] },
},
[97914] = { en="Expanding Horizons", ai=true,
[===[Нові обрії]===],
[===[Аубердін — скромне місце, {клас:к}. Його назви не почуєш серед гілля Дарнаса. Більшість згадує лише те, що забрав у нас Розкол, — квітучі міста Амет'Аран, Башал'Аран і... Латар'Лазал.

Та Аубердін і досі лишається в їхній тіні.

Я хотів би, щоб нашу працю тут визнали. Нове судно поєднує нас із королівством Штормовію, привозячи до наших берегів життя та припаси. Благаю тебе, вирушай у його наступний рейс і передай цей лист людині на ім'я Барос Алекстон.

Нехай про наш дім дізнаються.]===],
[===[Передайте лист Тандріса Баросу Алекстону в Штормовій.

Тандріс згадував про корабель в Аубердіні, який може вас туди доправити.]===],
[===[Від тебе пахне морем, {стать:друже:подруго}!

<Барос сміється.>

Що привело тебе в Штормовій?]===],
[===[<Барос розгортає лист і береться читати, а його усмішка поступово згасає.>]===],
},
[97915] = { en="Camping 101: Alchemy", ai=true,
[===[Основи таборування: алхімія]===],
[===[Отже, ти {стать:обрав:обрала} шлях алхіміка, щоб варити настої та зілля. Певен, у мандрах це тобі знадобиться.

